describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with upToGrams <= 0", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: -1, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 500 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 5.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            9.9,
          ),
      ).toThrow(RangeError);
    });

    it("accepts valid brackets and overflow", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [
              { upToGrams: 500, costCents: 300 },
              { upToGrams: 1000, costCents: 500 },
            ],
            800,
          ),
      ).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 800 },
      ],
      1200,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      const lines = [makeLine("a", 0, 2)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(0);
    });

    it("returns 0 when weight is undefined (treated as 0)", () => {
      const lines = [makeLine("a", undefined, 2)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(0);
    });

    it("selects correct bracket for weight at lower boundary", () => {
      // weight 500 → bracket upToGrams 500 → 300
      const lines = [makeLine("a", 250, 2)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(300);
    });

    it("selects correct bracket for weight exactly at boundary", () => {
      // weight 1000 → bracket upToGrams 1000 → 500
      const lines = [makeLine("a", 1000, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(500);
    });

    it("selects next bracket when weight exceeds first", () => {
      // weight 501 → bracket upToGrams 1000 → 500
      const lines = [makeLine("a", 501, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(500);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      // weight 3000 → overflow → 1200
      const lines = [makeLine("a", 1500, 2)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(1200);
    });

    it("uses last bracket cost as overflow when overflowCostCents not set", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ]);
      // weight 2000 → exceeds all → last bracket = 600
      const lines = [makeLine("a", 2000, 1)];
      expect(noOverflow.computeShippingCents(lines, 5000)).toBe(600);
    });

    it("correctly sums weight across multiple lines", () => {
      // 200*3 + 400*2 = 600 + 800 = 1400 → bracket upToGrams 2000 → 800
      const lines = [makeLine("a", 200, 3), makeLine("b", 400, 2)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(800);
    });
  });
});

