    cart.add(widget, 2);
    expect(cart.itemCount).toBe(2);
  });

  it("add merges quantity for same product", () => {
    const cart = new Cart();
    cart.add(widget, 2);
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add throws for non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(widget, 0)).toThrow(RangeError);
    expect(() => cart.add(widget, -1)).toThrow(RangeError);
  });

  it("add throws for non-integer quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(widget, 1.5)).toThrow(RangeError);
  });

  it("add throws for negative unitPriceCents", () => {
    const cart = new Cart();
    const bad: Product = { id: "x", name: "X", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(cart.remove("w1")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    const cart = new Cart();
    cart.add(widget, 3);
    cart.updateQuantity("w1", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the line", () => {
    const cart = new Cart();
    cart.add(widget, 3);
    cart.updateQuantity("w1", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for negative quantity", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w1", -1)).toThrow(RangeError);
  });

  it("updateQuantity throws for non-integer quantity", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w1", 2.5)).toThrow(RangeError);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("nope", 1)).toThrow(
      "Product nope is not in the cart",
    );
  });

  it("clear removes all lines", () => {
    const cart = new Cart();
    cart.add(widget, 2);
    cart.add(gadget, 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0].product.id).toBe("w1");
    // mutating snapshot does not affect cart
    (snap[0] as { quantity: number }).quantity = 99;
    expect(cart.itemCount).toBe(1);
  });
});

describe("Cart - pricing pipeline (totals)", () => {
  it("computes subtotal as sum of price * quantity", () => {
    const cart = new Cart();
    cart.add(widget, 2); // 2000
    cart.add(gadget, 1); // 2000
