    });

    it("returns flat fee when no freeOverCents configured", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents([makeLine("a", 500, 2)], 100000)).toBe(500);
    });

    it("freeOverCents of 0 means always free for non-empty cart with subtotal >= 0", () => {
      const calc = new FlatShippingCalculator(500, 0);
      expect(calc.computeShippingCents([makeLine("a", 500, 1)], 0)).toBe(0);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with upToGrams <= 0", () => {
