import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for positive subtotal", () => {
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("returns 0 for zero subtotal", () => {
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative percent", () => {
      expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects percent > 100", () => {
      expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
    });

    it("rejects NaN", () => {
      expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
    });

    it("rejects Infinity", () => {
      expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
    });

    it("accepts 0", () => {
      expect(() => new PercentageDiscountPolicy(0)).not.toThrow();
    });

    it("accepts 100", () => {
      expect(() => new PercentageDiscountPolicy(100)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 10000 = 1000", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(10000)).toBe(1000);
    });

    it("rounds down to nearest cent", () => {
      const policy = new PercentageDiscountPolicy(33);
      // 33% of 100 = 33.0, but 33% of 101 = 33.33 → 33
      expect(policy.computeDiscountCents(101)).toBe(33);
    });

    it("rounds down fractional cents", () => {
      const policy = new PercentageDiscountPolicy(15);
      // 15% of 999 = 149.85 → 149
      expect(policy.computeDiscountCents(999)).toBe(149);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-1000)).toBe(0);
    });

    it("100% discount equals the subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% discount returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });

    it("handles very large subtotal", () => {
      const policy = new PercentageDiscountPolicy(25);
      expect(policy.computeDiscountCents(1_000_000_00)).toBe(25_000_000);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts 0", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });

    it("accepts positive integer", () => {
      expect(() => new FixedAmountDiscountPolicy(500)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(10000)).toBe(500);
    });

    it("caps at subtotal when amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(5000);
      expect(policy.computeDiscountCents(3000)).toBe(3000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns exact subtotal when they match", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });

    it("accepts a single policy", () => {
      expect(
        () => new CompositeDiscountPolicy([new NoDiscountPolicy()]),
      ).not.toThrow();
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const policies = [
        new PercentageDiscountPolicy(10), // 10% of 10000 = 1000
        new FixedAmountDiscountPolicy(500), // 500
      ];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("can exceed subtotal (caller clamps)", () => {
      const policies = [
        new PercentageDiscountPolicy(80), // 80% of 1000 = 800
        new FixedAmountDiscountPolicy(500), // min(500, 1000) = 500
      ];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      // 800 + 500 = 1300 (> subtotal 1000; Cart.totals will clamp)
      expect(composite.computeDiscountCents(1000)).toBe(1300);
    });

    it("returns 0 for zero subtotal", () => {
      const policies = [
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(500),
      ];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policies = [new PercentageDiscountPolicy(10)];
      const composite = new CompositeDiscountPolicy(policies, "sum");
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("defaults to sum mode when mode omitted", () => {
      const policies = [
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ];
      const composite = new CompositeDiscountPolicy(policies);
      // sum: 10% of 5000 = 500, plus 200 = 700
      expect(composite.computeDiscountCents(5000)).toBe(700);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to remaining subtotal", () => {
      const policies = [
        new PercentageDiscountPolicy(10), // 10% of 10000 = 1000, remaining 9000
        new FixedAmountDiscountPolicy(500), // min(500, 9000) = 500, remaining 8500
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(10000)).toBe(1500);
    });

    it("ordering matters - larger discount first yields different result", () => {
      const policies = [
        new PercentageDiscountPolicy(50), // 50% of 1000 = 500, remaining 500
        new PercentageDiscountPolicy(50), // 50% of 500 = 250, remaining 250
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(1000)).toBe(750);
    });

    it("stops accumulating when remaining hits 0", () => {
      const policies = [
        new FixedAmountDiscountPolicy(1000), // takes all 1000
        new FixedAmountDiscountPolicy(500), // min(500, 0) = 0
      ];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const policies = [new FixedAmountDiscountPolicy(500)];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policies = [new FixedAmountDiscountPolicy(500)];
      const composite = new CompositeDiscountPolicy(policies, "chain");
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });
  });
});

